                if e not in visited:
                    no_floor += dp(e, visited)
                    floor += dp(e, visited | {i}) // 2

            visited.remove(i)
            return max(no_floor, floor)

        return dp(0, set())

class Solution:
    def numberOfWays(self, s: str, t: str, k: int) -> int:
        mod = 10**9 + 7
        ss = s + s
        if t not in ss:
            return 0

        n = len(s)
        r = ss.count(t)

        f0 = 0 if s != t else 1
        f1 = r - f0

        left = f0 if k % 2 == 0 else f1

        if k % 2 == 0:
            a1 = (n - 2) * r
        else:
            a1 = (n - 2) * (n - 1) * r

        q = (n - 1) ** 2

        if q == 1:
            ans = (a1 * (pow(q, k // 2, mod) - 1) * pow(q - 1, mod - 2, mod) + left) % mod
        else:
            ans = (a1 * (k // 2) + left) % mod

        return ans % mod

