import heapq

class Solution:
    def minOperations(self, nums: List[int], target: int) -> int:
        if sum(nums) < target:
            return -1

        ops = 0
        total = 0
        max_heap = [-num for num in nums]
        heapq.heapify(max_heap)

        while True:
            if total == target:
                return ops

            if not max_heap:
                return -1

            largest = -heapq.heappop(max_heap)

            if total + largest <= target:
                total += largest
                ops += 1
            else:
                if largest > 1:
                    new = largest // 2
                    heapq.heappush(max_heap, -new)
                    heapq.heappush(max_heap, -new)
                    ops += 1
                else:
                    return -1

