class Solution:
    def getMaxFunctionValue(self, receiver: List[int], k: int) -> int:
        n = len(receiver)
        up = [[0] * 40 for _ in range(n)]

        for i in range(n):
            up[i][0] = receiver[i]
            for j in range(1, 40):
                up[i][j] = up[up[i][j - 1]][j - 1]

        ans = 0

        for i in range(n):
            tot = i
            u = i

            for j in range(40):
                if k & (1 << j):
                    u = up[u][j]
                    tot += u

            ans = max(ans, tot)

        return ans

