class Solution:
    def longestValidSubstring(self, word: str, forbidden: List[str]) -> int:
        if not word:
            return 0

        forbidden_set = set(forbidden)
        res = 0
        n = len(word)

        for left in range(n):
            for k in range(left, min(left + 10, n)):
                if word[left:k + 1] in forbidden_set:
                    break
            else:
                res = max(res, k - left + 1)

        return res
